require("autostart")
require("bindings")
require("envs")
require("looknfeel")
require("input")
require("windows")
require("monitors")

-- Border colors from the current theme, generated by omarchy-theme-set
local state_home = os.getenv("XDG_STATE_HOME") or (os.getenv("HOME") .. "/.local/state")
local theme_hyprland = state_home .. "/desktop/current/theme/hyprland.lua"
local theme_file = io.open(theme_hyprland, "r")
if theme_file then
  theme_file:close()
  dofile(theme_hyprland)
end
